/*
 * AnimationSet.h:
 *  Per-state animation clips for a character sprite (idle, walk, attack, cast, hurt, death).
 *  Defined from Lua with Data.animation_set_create (see runtime/classes/AnimationSets.lua, generated by
 *  tools/sprites/build.py) and keyed by the sprite they animate.
 */

#ifndef ANIMATIONSET_H_
#define ANIMATIONSET_H_

#include <vector>

#include "lanarts_defines.h"

class LuaStackValue;

struct AnimationClip {
	sprite_id sprite = -1;
	// How many game steps each frame is shown for
	std::vector<int> frame_steps;
	bool loop = false;

	bool valid() const {
		return sprite != -1 && !frame_steps.empty();
	}
	int total_steps() const;
	// The frame shown 'elapsed' steps after the clip started; loops, or holds the last frame
	int frame_at(int elapsed) const;
	bool playing(int elapsed) const {
		return valid() && elapsed >= 0 && (loop || elapsed < total_steps());
	}
};

struct AnimationSet {
	AnimationClip idle, walk, attack, cast, hurt, death;
};

namespace res {
	// The animations for a sprite, or nullptr if it has none
	const AnimationSet* animation_set(::sprite_id sprite);
}

void lapi_data_create_animation_set(const LuaStackValue& table);
void clear_animation_sets();

#endif /* ANIMATIONSET_H_ */
